Got it, ties break by first appearance in the input, not alphabetical. So I'll track the first index each word appears at, and when two counts are equal, the smaller index wins. Let me use a min-heap of size k keyed on count, then first index, and walk the words once.

```js
function topKWords(words, k) {
  const count = new Map();
  const first = new Map();
  words.forEach((w, i) => {
    count.set(w, (count.get(w) || 0) + 1);
    if (!first.has(w)) first.set(w, i);
  });

  const better = (a, b) =>
    count.get(a) !== count.get(b)
      ? count.get(a) > count.get(b)
      : first.get(a) < first.get(b);

  const heap = [];
  const swap = (i, j) => ([heap[i], heap[j]] = [heap[j], heap[i]]);
  const siftUp = (i) => {
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (better(heap[i], heap[p])) { swap(i, p); i = p; } else break;
    }
  };
  const siftDown = (i) => {
    for (;;) {
      let s = i;
      const l = 2 * i + 1, r = 2 * i + 2;
      if (l < heap.length && better(heap[l], heap[s])) s = l;
      if (r < heap.length && better(heap[r], heap[s])) s = r;
      if (s === i) break;
      swap(i, s); i = s;
    }
  };

  for (const w of count.keys()) {
    heap.push(w);
    siftUp(heap.length - 1);
    if (heap.length > k) {
      swap(0, heap.length - 1);
      heap.pop();
      siftDown(0);
    }
  }

  return heap.sort((a, b) => (better(a, b) ? -1 : 1));
}
```

Time is O(n log k), space O(n) for the maps plus O(k) for the heap. The only change from the sheet is the tiebreak: first index instead of alphabetical.

